uniform float speed : 0.0 .. 5.0 = 1.0;
state float phase;
void update() {
  phase = phase + dt * speed;
}
vec3 shade(Led led) {
  float v = 0.5 + 0.5 * sin(phase + led.s * 6.2832);
  return vec3(v, 0.0, 0.0);
}

