uniform float speed : 0.0 .. 5.0 = 1.0;
uniform vec2 radius : 0.0 .. 1.0 = vec2(0.5, 0.5);
uniform int spokes : 3 .. 6 = 4;
state float phase;
state int idx;
void update() {
  phase += dt * speed; idx = (idx + 1) % spokes;
}
vec3 shade(Led led) {
  vec3 v = vec3(0.5, 0.5, 0.5); for(int i = 0; i < spokes; ++i) { float angle = 2.0 * pi * phase / spokes; v += sin(angle + radius.x * idx % 1) * cos(radius.y * idx) + vec3(0.1, 0.4, 0.9); } return v;
}

uniform float speed : 0.1 .. 2.0 = 0.5;
state int breath_count;
void update() {
  breath_count = breath_count + dt * speed;
}
vec3 shade(Led led) {
  return vec3(1, 0, 0) * smoothstep(breath_count, breath_count + 2, float(dt));
}

uniform float speed : 0.0 .. 5.0 = 1.0;
